package com.priperi;
import android.content.Context;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.*;import java.util.*;import java.util.concurrent.*;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class MessageActionsFlowTest {
 Context context;Vault other;String peer,me;
 void local(Repository.Job<Boolean> job)throws Exception{CountDownLatch done=new CountDownLatch(1);Throwable[] error={null};Repository.local(context,v->{try{return job.run(v);}catch(Throwable e){error[0]=e;return false;}},ok->done.countDown(),m->{error[0]=new AssertionError(m);done.countDown();});assertTrue(done.await(45,TimeUnit.SECONDS));if(error[0]!=null)throw new AssertionError(error[0]);}
 @Before public void setup()throws Exception{Assume.assumeTrue("yes".equals(InstrumentationRegistry.getArguments().getString("actions")));context=ApplicationProvider.getApplicationContext();assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));context.getSharedPreferences("notification_access",0).edit().putBoolean("asked",true).commit();Repository.reset();other=new Vault(context,"actions_"+UUID.randomUUID());local(v->{if(v.account()!=null)throw new SecurityException("Disposable installation required");Session.continueAccount(v,"qa_act_"+UUID.randomUUID().toString().substring(0,8),"Actions-Test-2026!");me=Session.uid();Session.continueAccount(other,"qa_act_"+UUID.randomUUID().toString().substring(0,8),"Actions-Test-2026!");peer=Session.uid();TestIdentityTrust.pin(other,Repository.lookup(other,v.account().getString("username")));Session.restore(v);TestIdentityTrust.pin(v,Repository.lookup(v,other.account().getString("username")));Repository.send(v,peer,"Contact request");Repository.sync(v);Session.restore(other);Repository.sync(other);Repository.approveContact(other,me);other.clearHistory(me);Session.restore(v);Repository.sync(v);v.clearHistory(peer);return true;});}
 @After public void cleanup()throws Exception{if(other==null)return;local(v->{Session.restore(other);Session.resetAccount(other);Session.restore(v);Session.resetAccount(v);Repository.eraseLocal(v);return true;});other.destroy();Repository.reset();}
 @Test public void encryptedDirectEditReplyAndDeleteRoundTrip()throws Exception{local(v->{JSONObject original=TestIdentityTrust.send(v,peer,"Original private text",null);String id=original.getJSONObject("envelope").getString("id");Repository.sync(v);Session.restore(other);Repository.sync(other);assertEquals("Original private text",other.message(id).getString("body"));Session.restore(v);TestIdentityTrust.change(v,peer,id,"Corrected private text",false);Repository.sync(v);Session.restore(other);Repository.sync(other);assertEquals("Corrected private text",other.message(id).getString("body"));assertTrue(other.message(id).getBoolean("edited"));assertEquals("",other.message(id).getJSONObject("envelope").getString("ciphertext"));JSONObject reply=TestIdentityTrust.send(other,me,"Answer",id);String replyId=reply.getJSONObject("envelope").getString("id");Repository.sync(other);Session.restore(v);Repository.sync(v);assertEquals(id,v.message(replyId).getString("replyTo"));assertEquals("Answer",v.message(replyId).getString("body"));TestIdentityTrust.change(v,peer,id,null,true);Repository.sync(v);Session.restore(other);Repository.sync(other);assertTrue(other.message(id).getBoolean("deleted"));assertEquals("",other.message(id).getString("body"));assertEquals("",other.message(id).getJSONObject("envelope").getString("ciphertext"));assertTrue(other.messages(me).stream().noneMatch(m->m.optBoolean("hidden")));assertEquals(0,Repository.call(other,"syncInbox",new JSONObject()).getJSONArray("messages").length());Session.restore(v);return true;});}
 @Test public void outOfOrderChangesRejectOtherAuthorsAndNeverResurrect()throws Exception{local(v->{long at=System.currentTimeMillis()-1000;String id=UUID.randomUUID().toString();JSONObject original=envelope(other,v,"Before",id,at,null,0);JSONObject deletion=envelope(other,v,MessageContent.change(true,id,at,0,null),UUID.randomUUID().toString(),at+300,null,0);deliver(v,other,deletion);deliver(v,other,original);assertTrue(v.message(id).getBoolean("deleted"));JSONObject olderEdit=envelope(other,v,MessageContent.change(false,id,at,0,"Should not return"),UUID.randomUUID().toString(),at+200,null,0);deliver(v,other,olderEdit);assertEquals("",v.message(id).getString("body"));assertTrue(v.seen(olderEdit));JSONObject own=TestIdentityTrust.send(v,peer,"My message",null);String mine=own.getJSONObject("envelope").getString("id");JSONObject attack=envelope(other,v,MessageContent.change(false,mine,own.getJSONObject("envelope").getLong("sentAt"),0,"Forged"),UUID.randomUUID().toString(),System.currentTimeMillis(),null,0);assertThrows(java.security.GeneralSecurityException.class,()->deliver(v,other,attack));assertFalse(v.seen(attack));assertEquals("My message",v.message(mine).getString("body"));Session.restore(other);Repository.call(other,"sendMessage",new JSONObject().put("message",attack));Session.restore(v);assertTrue(Repository.sync(v).contains("ignored"));assertTrue(v.seen(attack));assertEquals("My message",v.message(mine).getString("body"));String unknownId=UUID.randomUUID().toString();JSONObject unknown=envelope(other,v,MessageContent.MAGIC+"2:AA==",unknownId,System.currentTimeMillis(),null,0);Session.restore(other);Repository.call(other,"sendMessage",new JSONObject().put("message",unknown));Session.restore(v);assertTrue(Repository.sync(v).contains("unsupported"));assertTrue(v.message(unknownId).getBoolean("unsupported"));assertFalse(v.message(unknownId).getJSONObject("envelope").getString("ciphertext").isEmpty());assertTrue(v.seen(unknown));assertEquals(0,Repository.call(v,"syncInbox",new JSONObject()).getJSONArray("messages").length());assertThrows(SecurityException.class,()->TestIdentityTrust.change(v,peer,id,"Not mine",false));return true;});}
 @Test public void localDeleteSurvivesOldBackupAndPendingOutboxCannotBeBypassed()throws Exception{local(v->{JSONObject original=TestIdentityTrust.send(v,peer,"Do not restore this",null);String id=original.getJSONObject("envelope").getString("id");Repository.sync(v);byte[] salt=new byte[16],key=new byte[32];File file=new File(context.getCacheDir(),"actions-test.backup");try{v.exportMessages(file,key,salt,()->{});v.deleteMessage(peer,id);assertTrue(v.messages(peer).isEmpty());v.clearHistory(peer);v.restoreMessages(file,key,()->{});assertTrue(v.messages(peer).isEmpty());assertEquals("",v.message(id).getString("body"));assertEquals("",v.message(id).getJSONObject("envelope").getString("ciphertext"));}finally{file.delete();}JSONObject queued=TestIdentityTrust.send(v,peer,"Already queued",null);String qid=queued.getJSONObject("envelope").getString("id");v.deleteMessage(peer,qid);assertEquals("pending",v.message(qid).getString("state"));assertFalse(v.message(qid).getJSONObject("envelope").getString("ciphertext").isEmpty());Repository.sync(v);assertEquals("",v.message(qid).getJSONObject("envelope").getString("ciphertext"));Session.restore(other);Repository.sync(other);assertEquals("Already queued",other.message(qid).getString("body"));Session.restore(v);return true;});}
 @Test public void groupChangesRequireSameGroupVersionAndSender()throws Exception{local(v->{String gid=UUID.randomUUID().toString();long at=System.currentTimeMillis()-1000;String id=UUID.randomUUID().toString();JSONObject original=envelope(other,v,"Group original",id,at,gid,1);deliver(v,other,original);JSONObject edit=envelope(other,v,MessageContent.change(false,id,at,1,"Group corrected"),UUID.randomUUID().toString(),at+100,gid,1);deliver(v,other,edit);assertEquals("Group corrected",v.message(id).getString("body"));JSONObject wrong=envelope(other,v,MessageContent.change(false,id,at,2,"Wrong epoch"),UUID.randomUUID().toString(),at+200,gid,2);assertThrows(java.security.GeneralSecurityException.class,()->deliver(v,other,wrong));JSONObject cross=envelope(other,v,MessageContent.change(true,id,at,1,null),UUID.randomUUID().toString(),at+300,UUID.randomUUID().toString(),1);assertThrows(java.security.GeneralSecurityException.class,()->deliver(v,other,cross));assertFalse(v.message(id).optBoolean("deleted"));JSONObject expired=envelope(other,v,MessageContent.change(false,id,at,1,"Too late"),UUID.randomUUID().toString(),at+MessageContent.EDIT_WINDOW+1,gid,1);assertThrows(java.security.GeneralSecurityException.class,()->deliver(v,other,expired));return true;});}
 @Test public void longPressReplyRotationEditAndLocalDeleteRemainUsable()throws Exception {
  String[] id={null};local(v->{JSONObject m=TestIdentityTrust.send(v,peer,"UI original",null);id[0]=m.getJSONObject("envelope").getString("id");Repository.sync(v);return true;});
  try(androidx.test.core.app.ActivityScenario<ChatActivity> screen=androidx.test.core.app.ActivityScenario.launch(new android.content.Intent(context,ChatActivity.class).putExtra("peer",peer))){
   await(screen,a->find(a.root,"UI original")!=null);screen.onActivity(a->{find(a.root,"UI original").performLongClick();choose(a,"Reply");});screen.recreate();await(screen,a->findDescription(a.root,"Reply · UI original")!=null);
   screen.onActivity(a->{((android.widget.EditText)findComposer(a.root)).setText("UI answer");findDescription(a.root,"Send message").performClick();});await(screen,a->find(a.root,"UI answer")!=null);
   screen.onActivity(a->{find(a.root,"UI original").performLongClick();choose(a,"Edit");androidx.appcompat.app.AlertDialog d=dialog(a);android.widget.EditText edit=(android.widget.EditText)findInput(d.getWindow().getDecorView());edit.setText("UI corrected");});InstrumentationRegistry.getInstrumentation().waitForIdleSync();screen.onActivity(a->dialog(a).getButton(-1).performClick());await(screen,a->find(a.root,"UI corrected")!=null);
   screen.onActivity(a->{find(a.root,"UI corrected").performLongClick();choose(a,"Delete for me");dialog(a).getButton(-1).performClick();});await(screen,a->find(a.root,"UI corrected")==null);local(v->{assertTrue(v.message(id[0]).getBoolean("localDeleted"));assertTrue(v.messages(peer).stream().anyMatch(m->id[0].equals(m.optString("replyTo"))));return true;});
  }
 }
 @Test public void savedChangeStillSendsAfterLeavingChat()throws Exception {
  String[] id={null};local(v->{JSONObject m=TestIdentityTrust.send(v,peer,"Before leaving",null);id[0]=m.getJSONObject("envelope").getString("id");Repository.sync(v);return true;});CountDownLatch blocked=new CountDownLatch(1),release=new CountDownLatch(1);
  try(androidx.test.core.app.ActivityScenario<ChatActivity> s=androidx.test.core.app.ActivityScenario.launch(new android.content.Intent(context,ChatActivity.class).putExtra("peer",peer))){
   await(s,a->find(a.root,"Before leaving")!=null);s.onActivity(a->{find(a.root,"Before leaving").performLongClick();choose(a,"Edit");((android.widget.EditText)findInput(dialog(a).getWindow().getDecorView())).setText("Saved while leaving");});InstrumentationRegistry.getInstrumentation().waitForIdleSync();
   Repository.local(context,v->{blocked.countDown();release.await(15,TimeUnit.SECONDS);return true;},ok->{},error->{});assertTrue(blocked.await(10,TimeUnit.SECONDS));s.onActivity(a->dialog(a).getButton(-1).performClick());s.moveToState(androidx.lifecycle.Lifecycle.State.CREATED);release.countDown();
   boolean[] sent={false};for(int i=0;i<50&&!sent[0];i++){local(v->{sent[0]="sent".equals(v.message(id[0]).optString("changeState"));return true;});if(!sent[0])android.os.SystemClock.sleep(100);}assertTrue("Leaving the screen stranded an authorized update",sent[0]);s.moveToState(androidx.lifecycle.Lifecycle.State.RESUMED);
  }finally{release.countDown();}
 }
 interface Ready{boolean ok(ChatActivity a);}static void await(androidx.test.core.app.ActivityScenario<ChatActivity> s,Ready r){for(int i=0;i<120;i++){boolean[] ok={false};s.onActivity(a->ok[0]=r.ok(a));if(ok[0])return;android.os.SystemClock.sleep(100);}fail("Chat action UI did not update");}
 static androidx.appcompat.app.AlertDialog dialog(ChatActivity a){try{java.lang.reflect.Field f=ChatActivity.class.getDeclaredField("actionDialog");f.setAccessible(true);return (androidx.appcompat.app.AlertDialog)f.get(a);}catch(Exception e){throw new AssertionError(e);}}
 static void choose(ChatActivity a,String text){android.widget.ListView list=dialog(a).getListView();for(int i=0;i<list.getAdapter().getCount();i++)if(text.equals(list.getAdapter().getItem(i).toString())){list.performItemClick(null,i,i);return;}fail("Missing action "+text);}
 static android.view.View find(android.view.View v,String text){if(v instanceof android.widget.TextView&&text.contentEquals(((android.widget.TextView)v).getText()))return v;return children(v,c->find(c,text));}
 static android.view.View findDescription(android.view.View v,String text){if(text.equals(v.getContentDescription()))return v;return children(v,c->findDescription(c,text));}
 static android.view.View findComposer(android.view.View v){if(v instanceof android.widget.EditText&&"Message".contentEquals(((android.widget.EditText)v).getHint()))return v;return children(v,MessageActionsFlowTest::findComposer);}
 static android.view.View findInput(android.view.View v){if(v instanceof android.widget.EditText)return v;return children(v,MessageActionsFlowTest::findInput);}
 interface Find{android.view.View get(android.view.View v);}static android.view.View children(android.view.View v,Find find){if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){android.view.View found=find.get(g.getChildAt(i));if(found!=null)return found;}}return null;}
 static JSONObject envelope(Vault sender,Vault receiver,String wire,String id,long at,String group,int version)throws Exception{return sender.crypto().encryptGroup(sender.account().getString("uid"),sender.identity(),receiver.account(),wire,id,at,group,version);}
 static void deliver(Vault receiver,Vault sender,JSONObject env)throws Exception{String wire=receiver.crypto().decrypt(receiver.account().getString("uid"),receiver.identity(),sender.account(),env);receiver.store(MessageActions.decode(new JSONObject().put("peer",env.has("group")?"group:"+env.getString("group"):env.getString("sender")).put("outgoing",false).put("state","received").put("author",sender.account()).put("envelope",env),wire));}
}
